CustomField.formula:
IF( Pending_Action__c , 'Pending Action', 
    IF(ISPICKVAL(Bgive_IM_Connection__c , 'Not Applicable'), 
         'Not In Bgive',
         IF(
            AND(
                NOT(ISBLANK(Amendment_Bgive_Id__c)),  
                NBI_Budget_Amount_Local__c +  Confirmed_Budget_Amount_Local__c  =  Amendment_Future_Amount_Local__c
            ), 
            'Amendment In Progress',
            Bgive_Status__c 
         )
    )
)
